class Solution:
    def maxSum(self, nums: List[int]) -> int:
        def max_digit(x):
            m = 0
            while x:
                m = max(m, x % 10)
                x //= 10
            return m
        best = {}
        ans = -1
        for v in nums:
            d = max_digit(v)
            if d in best:
                ans = max(ans, best[d] + v)
                best[d] = max(best[d], v)
            else:
                best[d] = v
        return ans

