class Solution {
public:
    int maxSum(vector<int>& nums) {
        auto maxDigit = [](int x) {
            int m = 0;
            while (x) { m = max(m, x % 10); x /= 10; }
            return m;
        };
        unordered_map<int, int> best;
        int ans = -1;
        for (int v : nums) {
            int d = maxDigit(v);
            auto it = best.find(d);
            if (it != best.end()) {
                ans = max(ans, it->second + v);
                it->second = max(it->second, v);
            } else best[d] = v;
        }
        return ans;
    }
};

