class Solution {
    public int maxSum(int[] nums) {
        Map<Integer, Integer> best = new HashMap<>();
        int ans = -1;
        for (int v : nums) {
            int d = 0, x = v;
            while (x > 0) { d = Math.max(d, x % 10); x /= 10; }
            if (best.containsKey(d)) {
                ans = Math.max(ans, best.get(d) + v);
                best.put(d, Math.max(best.get(d), v));
            } else best.put(d, v);
        }
        return ans;
    }
}

