class Solution {
    public int maxSum(int[] nums) {
        int ans = -1, n = nums.length;
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++) {
                int a = 0, x = nums[i], b = 0, y = nums[j];
                while (x > 0) { a = Math.max(a, x % 10); x /= 10; }
                while (y > 0) { b = Math.max(b, y % 10); y /= 10; }
                if (a == b) ans = Math.max(ans, nums[i] + nums[j]);
            }
        return ans;
    }
}

